using FallenForest.Core;using UnityEngine;using UnityEngine.UI;namespace FallenForest.UI{public sealed class SettingsMenuController:MonoBehaviour{[SerializeField]private Slider sensitivitySlider,fovSlider,shakeSlider;[SerializeField]private Text sensitivityValue,fovValue,shakeValue;private void OnEnable(){if(sensitivitySlider!=null){sensitivitySlider.minValue=.3f;sensitivitySlider.maxValue=2.5f;sensitivitySlider.value=GameSettings.Sensitivity;}if(fovSlider!=null){fovSlider.minValue=60;fovSlider.maxValue=100;fovSlider.value=GameSettings.Fov;}if(shakeSlider!=null){shakeSlider.minValue=0;shakeSlider.maxValue=1;shakeSlider.value=GameSettings.CameraShake;}RefreshLabels();}public void SetSensitivity(float v){GameSettings.Sensitivity=v;RefreshLabels();}public void SetFov(float v){GameSettings.Fov=v;RefreshLabels();}public void SetShake(float v){GameSettings.CameraShake=v;RefreshLabels();}private void RefreshLabels(){if(sensitivityValue!=null)sensitivityValue.text=$"{GameSettings.Sensitivity:0.00}x";if(fovValue!=null)fovValue.text=$"{GameSettings.Fov:0}°";if(shakeValue!=null)shakeValue.text=$"{GameSettings.CameraShake*100f:0}%";}}}
